curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "limit=999" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data['members']:
        if 'diego' in u.get('profile',{}).get('display_name','').lower() or 'diego' in u.get('profile',{}).get('real_name','').lower() or 'alvarez' in u.get('profile',{}).get('real_name','').lower():
            print(json.dumps(u, indent=2))
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "types=private_channel&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for c in data['channels']:
        purpose = c.get('purpose', {}).get('value', '')
        if 'onboard' in purpose.lower():
            print(json.dumps(c, indent=2))
else:
    print(json.dumps(data, indent=2))
"
